<?php
require_once __DIR__ . '/scoring_rubrics.php';
$role = $_SESSION['role'] ?? '';
$params = [];
$sql = 'SELECT ScholarshipID, Name FROM scholarship';
if ($role === 'External_Admin') { $sql .= ' WHERE CreatedBy = ?'; $params[] = $_SESSION['user_id']; }
$sql .= ' ORDER BY Name';
$stmt = $pdo->prepare($sql); $stmt->execute($params); $scholarships = $stmt->fetchAll(PDO::FETCH_ASSOC);
$selectedId = (int) ($_GET['scholarship_id'] ?? ($scholarships[0]['ScholarshipID'] ?? 0));
$allowedIds = array_map('intval', array_column($scholarships, 'ScholarshipID'));
if ($selectedId && !in_array($selectedId, $allowedIds, true)) $selectedId = 0;
$rubric = $selectedId ? scholarshipRubric($pdo, $selectedId) : null;
$selectedName = '';
foreach ($scholarships as $s) if ((int)$s['ScholarshipID'] === $selectedId) $selectedName = $s['Name'];
?>
<main class="min-h-screen bg-slate-50 p-6 lg:p-10"><div class="max-w-6xl mx-auto">
<div class="mb-8"><p class="text-xs font-black text-violet-600 uppercase tracking-widest">Evaluation Governance</p><h1 class="text-3xl font-black text-slate-900 mt-2">Scoring Rubrics</h1><p class="text-slate-500 mt-2">Configure weighted criteria, passing rules, comments, tie breakers, and the authorized override procedure.</p></div>
<?php if (!empty($_SESSION['success'])):?><div class="mb-5 p-4 rounded-xl bg-green-50 text-green-800 font-bold"><?=htmlspecialchars($_SESSION['success']);unset($_SESSION['success'])?></div><?php endif;?>
<?php if (!empty($_SESSION['error'])):?><div class="mb-5 p-4 rounded-xl bg-red-50 text-red-800 font-bold"><?=htmlspecialchars($_SESSION['error']);unset($_SESSION['error'])?></div><?php endif;?>
<form method="get" class="bg-white border border-slate-200 rounded-2xl p-5 mb-6"><label class="text-xs font-black uppercase text-slate-500">Scholarship<select name="scholarship_id" onchange="this.form.submit()" class="mt-2 w-full rounded-xl border border-slate-200 p-3 font-bold"><option value="">Select scholarship</option><?php foreach($scholarships as $s):?><option value="<?=$s['ScholarshipID']?>" <?=$selectedId===(int)$s['ScholarshipID']?'selected':''?>><?=htmlspecialchars($s['Name'])?></option><?php endforeach;?></select></label></form>
<?php if($rubric):?><form method="post" action="../actions/process_scoring_rubric.php" class="bg-white border border-slate-200 rounded-3xl p-6 lg:p-8 shadow-sm space-y-7"><input type="hidden" name="scholarship_id" value="<?=$selectedId?>">
<div><h2 class="text-xl font-black text-slate-900"><?=htmlspecialchars($selectedName)?></h2><p class="text-xs text-slate-500 mt-1">Weights must total exactly 100%. Existing submitted applications retain their frozen rubric version.</p></div>
<div class="grid md:grid-cols-3 gap-4"><label class="text-xs font-black uppercase text-slate-500">Passing score (out of 100)<input type="number" name="passing_score" min="0" max="100" step="0.01" required value="<?=htmlspecialchars($rubric['PassingScore'])?>" class="mt-2 w-full p-3 rounded-xl border border-slate-200"></label><label class="text-xs font-black uppercase text-slate-500">Display maximum<input type="number" name="total_maximum" min="1" step="0.01" required value="<?=htmlspecialchars($rubric['TotalMaximumScore'])?>" class="mt-2 w-full p-3 rounded-xl border border-slate-200"></label><label class="flex gap-3 items-center mt-6 p-4 bg-blue-50 rounded-xl font-bold text-sm"><input type="checkbox" name="general_comments_required" value="1" <?=!empty($rubric['GeneralCommentsRequired'])?'checked':''?>> Require overall evaluator comments</label></div>
<div class="overflow-x-auto"><table class="no-datatable w-full text-sm"><thead><tr class="text-left text-xs uppercase text-slate-500"><th class="p-3">Criterion</th><th class="p-3">Weight %</th><th class="p-3">Maximum</th><th class="p-3">Criterion pass</th><th class="p-3">Tie priority</th><th class="p-3">Comment</th></tr></thead><tbody><?php foreach($rubric['criteria'] as $i=>$c):?><tr class="border-t border-slate-100"><td class="p-3 font-black"><?=htmlspecialchars($c['CriteriaName'])?><input type="hidden" name="criteria_ids[]" value="<?=$c['CriteriaID']?>"></td><td class="p-3"><input name="weights[]" type="number" min="0.01" max="100" step="0.01" required value="<?=$c['WeightPercent']?>" class="w-24 p-2 border rounded-lg"></td><td class="p-3"><input name="maximum_scores[]" type="number" min="0.01" step="0.01" required value="<?=$c['MaximumScore']?>" class="w-24 p-2 border rounded-lg"></td><td class="p-3"><input name="criterion_passing_scores[]" type="number" min="0" step="0.01" value="<?=$c['PassingScore']?>" class="w-24 p-2 border rounded-lg" placeholder="Optional"></td><td class="p-3"><input name="tie_priorities[]" type="number" min="1" value="<?=$c['TieBreakPriority']?>" class="w-20 p-2 border rounded-lg" placeholder="—"></td><td class="p-3"><input type="hidden" name="comment_required[<?=$i?>]" value="0"><label class="font-bold"><input type="checkbox" name="comment_required[<?=$i?>]" value="1" <?=!empty($c['CommentRequired'])?'checked':''?>> Required</label></td></tr><?php endforeach;?></tbody></table></div>
