<label class="block text-xs font-black uppercase text-slate-500">Tie-breaking rules<textarea name="tie_breaking_rules" minlength="10" required rows="3" class="mt-2 w-full p-3 border rounded-xl"><?=htmlspecialchars($rubric['TieBreakingRules'])?></textarea></label>
<label class="block text-xs font-black uppercase text-slate-500">Score override procedure<textarea name="override_procedure" minlength="10" required rows="3" class="mt-2 w-full p-3 border rounded-xl"><?=htmlspecialchars($rubric['OverrideProcedure'])?></textarea><span class="block mt-2 normal-case font-medium text-slate-400">Overrides are restricted to Super Admin and always require a reason and audit entry.</span></label>
<button <?=$rubric['criteria']?'':'disabled'?> class="w-full md:w-auto px-7 py-3 rounded-xl bg-slate-900 text-white font-black uppercase text-xs tracking-widest disabled:opacity-40">Save Rubric Version</button></form><?php endif;?>
